mapper.select:
SELECT mqca.*, mbp.id AS 'process.id', mbp.name AS 'process.name' FROM mes_quota_config_assemble mqca LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = mqca.process_id WHERE mqca.bool_delete_enum = 0
AND FIND_IN_SET(#{branchCompanyId}, mqca.branch_company_ids) > 0
AND FIND_IN_SET(#{workshopId}, mqca.workshop_ids) > 0
AND FIND_IN_SET(#{productClassId}, mqca.assemble_class_ids) > 0
AND mqca.process_id = #{processId}
AND (
FIND_IN_SET(#{bcId}, mqca.branch_company_ids) > 0
)
AND (
FIND_IN_SET(#{wId}, mqca.workshop_ids) > 0
)
AND (
FIND_IN_SET(#{pcId}, mqca.assemble_class_ids) > 0
)
AND (
mqca.process_id = #{pId}
)
